CREATE TABLE security_policies(organization_id uuid NOT NULL REFERENCES organizations(id),brand_id uuid NOT NULL,environment_id uuid NOT NULL,product_instance_id uuid PRIMARY KEY,require_staff_mfa boolean NOT NULL DEFAULT false,role_ids jsonb NOT NULL DEFAULT '[]',user_ids jsonb NOT NULL DEFAULT '[]',updated_by uuid NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,brand_id,environment_id,product_instance_id) REFERENCES product_instances(organization_id,brand_id,environment_id,id),CHECK(jsonb_typeof(role_ids)='array' AND jsonb_typeof(user_ids)='array'));
CREATE TABLE webhook_attempts(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),delivery_id uuid NOT NULL,attempt_number integer NOT NULL,response_status integer,error_code text,started_at timestamptz NOT NULL,completed_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,delivery_id) REFERENCES webhook_deliveries(organization_id,id));
ALTER TABLE security_policies ENABLE ROW LEVEL SECURITY; ALTER TABLE security_policies FORCE ROW LEVEL SECURITY;
ALTER TABLE webhook_attempts ENABLE ROW LEVEL SECURITY; ALTER TABLE webhook_attempts FORCE ROW LEVEL SECURITY;
CREATE POLICY security_policies_scope ON security_policies TO azuriya_app USING(current_setting('azuriya.core',true)='true' OR organization_id::text=NULLIF(current_setting('azuriya.organization_id',true),'')) WITH CHECK(current_setting('azuriya.core',true)='true' OR organization_id::text=NULLIF(current_setting('azuriya.organization_id',true),''));
CREATE POLICY webhook_attempts_scope ON webhook_attempts TO azuriya_app USING(current_setting('azuriya.core',true)='true' OR organization_id::text=NULLIF(current_setting('azuriya.organization_id',true),'')) WITH CHECK(current_setting('azuriya.core',true)='true' OR organization_id::text=NULLIF(current_setting('azuriya.organization_id',true),''));
GRANT SELECT,INSERT,UPDATE,DELETE ON security_policies TO azuriya_app;
GRANT SELECT,INSERT ON webhook_attempts TO azuriya_app;
CREATE INDEX webhook_attempt_history ON webhook_attempts(organization_id,delivery_id,started_at);
